DROP TABLE IF EXISTS `material_information`;
CREATE TABLE `material_information`(material_information_id int(11) NOT NULL AUTO_INCREMENT COMMENT '物资信息ID',
`item_no` varchar(64) comment '物资编号',
`item_name` varchar(64) comment '物资名称',
